def state_sim(demand,forecast,means,lead,penalty,policy):
 stock=np.ceil(means*3);cash=np.maximum(means,1)*20;cap=np.ceil(np.maximum(means,1)*3);storage=np.ceil(np.maximum(means,1)*10);qty=np.zeros_like(stock);proc=np.zeros_like(stock);setup=np.zeros_like(stock);hold=np.zeros_like(stock);short=np.zeros_like(stock);served=np.zeros_like(stock);order_count=np.zeros_like(stock);pipeline=np.zeros((len(stock),7+lead+1));start=stock.copy();infeasible=np.zeros(len(stock),bool);warnings=[]
 for day in range(7):
  stock+=pipeline[:,day];infeasible|=stock>storage;outstanding=pipeline[:,day+1:].sum(axis=1)
  if policy=='no_replenishment':wanted=np.zeros_like(stock)
  elif policy=='reorder_point':wanted=np.where(stock+outstanding<=np.ceil(means*3),cap,0)
  else:wanted=np.maximum(0,np.ceil(forecast[:,day:min(7,day+lead+1)].sum(axis=1)+np.ceil(means)-stock-outstanding))
  affordable=np.maximum(0,np.floor(cash-.25));q=np.minimum(np.minimum(wanted,cap),affordable)
  # Safety repair, independent of performance: worst-case occupancy reservation.
  q=np.maximum(0,np.minimum(q,np.floor(storage-stock-outstanding)));pay=q+.25*(q>0);cash-=pay;proc+=q;setup+=.25*(q>0);order_count+=(q>0);qty+=q
  if lead==0:stock+=q
  else:pipeline[:,day+lead]+=q
  supplied=np.minimum(stock,demand[:,day]);stock-=supplied;short+=demand[:,day]-supplied;served+=supplied;hold+=stock*.01
 outstanding=pipeline[:,7:].sum(axis=1);cost=proc+setup+hold+short*penalty-stock;delta=start+qty-served-stock-outstanding
 return {'simulated_total_cost':float(cost.sum()),'procurement':float(proc.sum()),'setup':float(setup.sum()),'holding':float(hold.sum()),'shortage':float((short*penalty).sum()),'terminal_inventory_credit':float(stock.sum()),'shortage_units':float(short.sum()),'served_units':float(served.sum()),'demand_units':float(demand.sum()),'service_level':float(served.sum()/demand.sum()) if demand.sum() else None,'ending_stock_units':float(stock.sum()),'on_order_terminal_units':float(outstanding.sum()),'ordered_units':float(qty.sum()),'order_count':int(order_count.sum()),'episodes':len(stock),'infeasible_storage_episodes':int(infeasible.sum()),'conservation_max_abs_delta_units':float(abs(delta).max()),'stock_conservation_pass':bool(np.all(abs(delta)<1e-8))}
def alert(actual,forecasts,means,threshold):
 initial=np.ceil(means*3);shortage_day=np.argmax(np.cumsum(actual,axis=1)>initial[:,None],axis=1)+1;label=actual.sum(axis=1)>initial;score=forecasts.sum(axis=1)/np.maximum(initial,1);warning=score>threshold;tp=int((warning&label).sum());fp=int((warning&~label).sum());fn=int((~warning&label).sum());tn=int((~warning&~label).sum());leads=shortage_day[warning&label]
 return {'threshold':threshold,'label_type':'SIMULATED_EVENT_LABEL','warning_type':'SIMULATED_WARNING','episodes':len(label),'actual_simulated_positive_events':int(label.sum()),'warnings':int(warning.sum()),'TP':tp,'FP':fp,'FN':fn,'TN':tn,'precision':tp/(tp+fp) if tp+fp else None,'recall':tp/(tp+fn) if tp+fn else None,'false_positive_rate':fp/(fp+tn) if fp+tn else None,'missed_events':fn,'late_warnings':0,'warning_timing':'All warnings issued at episode origin; miss and early lead do not represent a live production monitor.','warning_lead_time_days_mean':float(leads.mean()) if len(leads) else None,'warning_lead_time_days_counts':{str(i):int((leads==i).sum()) for i in range(1,8)},'declared_utility_cost_units':fp+4*fn}
def run():
 t=time.monotonic();write(ROOT/'artifacts/frozen-simulation-config.v1.json',CONFIG)
 d=np.load(ROOT/'data/derived/daily-sales.npz');y=d['sales'][d['eligible']].astype(float);n=y.shape[1];cut=n-56;means=y[:,:cut].mean(axis=1);v_orig=np.arange(cut-1,n-28,7);t_orig=np.arange(n-29,n-1,7);v_orig=v_orig[v_orig+7<n-28];t_orig=t_orig[t_orig+7<n];mean_ep=np.repeat(means,len(t_orig));demand=np.stack([y[:,o+1:o+8] for o in t_orig],axis=1).reshape(-1,7);vactual=np.stack([y[:,o+1:o+8] for o in v_orig],axis=1).reshape(-1,7);vmeans=np.repeat(means,len(v_orig));vf=baseline(y,v_orig)['moving_average_28'].reshape(-1,7);tf=baseline(y,t_orig)['moving_average_28'].reshape(-1,7);vals={str(th):alert(vactual,vf,vmeans,th) for th in CONFIG['threshold_candidates']};threshold=min(CONFIG['threshold_candidates'],key=lambda th:vals[str(th)]['declared_utility_cost_units']);test_alert=alert(demand,tf,mean_ep,threshold)
