 out.update({'policy_version': 'dormathon.inventory-policy.0.4.1.1', 'request_id': 'uci-simulated-policy-study-v0411', 'knowledge_as_of': None, 'knowledge_as_of_reason': 'Each weekly episode uses its own frozen origin; this aggregate report has no single cutoff.', 'world_time': None, 'world_time_reason': 'Multiple nonoverlapping seven-day simulation episodes.', 'knowledge_mode': 'retrospective_transaction_time_assumption', 'provenance_refs': ['doi:10.24432/C5CG6D'], 'input_refs': ['frozen-split.v1.json', 'benchmark-report.v1.json'], 'data_revision': 'bcbe73b35f5b7babf197fb0cb983a11f5d9ff929078d4aa53d171b1f2df2e980', 'warnings': ['Initial stock, lead times, capacities, budgets and all costs are invented scenario parameters within declared ranges.', 'Recorded positive sales are an exogenous proxy and cannot recover hidden demand.', 'Policies share identical initial inventory, test path and assumptions; true future demand enters transitions only, never order planning.', 'Scenario costs and service improvements are simulated, not observed savings or causal business benefits.', 'No operational MR D.I.Y. result, real shortage classifier or real warning quality is established.']})
 # Bootstrap alert precision/recall over SKU clusters, preserving all 4 episodes per item.
 label=demand.sum(axis=1)>np.ceil(mean_ep*3);warn=tf.sum(axis=1)/np.maximum(np.ceil(mean_ep*3),1)>threshold;cells=np.stack([warn&label,warn&~label,~warn&label,~warn&~label],axis=1).reshape(len(y),len(t_orig),4).sum(axis=1);rng=np.random.default_rng(SEED+2);stats=[]
 for _ in range(400):
  tp,fp,fn,tn=cells[rng.integers(0,len(y),len(y))].sum(axis=0);stats.append([tp/(tp+fp) if tp+fp else 0,tp/(tp+fn) if tp+fn else 0])
 out['alert_evaluation']['uncertainty'].update(method='SKU-cluster bootstrap, preserve four weekly episodes per sampled SKU',replicates=400,seed=SEED+2,precision_95pct_interval=np.quantile(np.array(stats)[:,0],[.025,.975]).tolist(),recall_95pct_interval=np.quantile(np.array(stats)[:,1],[.025,.975]).tolist());write(ROOT/'artifacts/simulated-policy-report.v1.json',out);print(json.dumps({'policies':policies,'alert':test_alert,'wall_seconds':out['wall_seconds']}))
